export { validateConfig as validateSellerServiceConfig };

export function resolveSellerConfigPaths(config, path) {
  for (const route of config.routes) {
    if (OWN(route, 'responseFile')) route.responseFile = resolve(dirname(resolve(path)), route.responseFile);
    if (OWN(route, 'responseAsset')) route.responseAsset.file = resolve(dirname(resolve(path)), route.responseAsset.file);
  }
  return config;
}

export async function readSellerConfig(path) {
  const info = await stat(path);
  if (!info.isFile() || info.size > 1024 * 1024) throw new TypeError('Config must be a regular JSON file up to 1 MiB');
  const bytes = await readFile(path);
  if (bytes.length > 1024 * 1024) throw new RangeError('Config exceeds 1 MiB');
  const config = validateConfig(JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)));
  return resolveSellerConfigPaths(config, path);
}

function facilitatorEndpoint(raw, allowLocal) {
  const url = new URL(raw);
  const local = allowLocal === true && url.protocol === 'http:' && url.hostname === HOST;
  if ((!local && url.protocol !== 'https:') || url.username || url.password || url.search || url.hash) {
    throw new TypeError('Facilitator requires HTTPS; local HTTP needs --allow-local-facilitator');
  }
  return url.href.replace(/\/$/, '');
}

/** Start one service. An embedding app can supply a nativeFactory for its own facilitator. */
export async function startSellerService({ config, port = 8423, handlers = {},
  nativeFactory = null, maxInFlight = 64, drainGraceMs = 60000, requestTimeoutMs, availabilityDirectory } = {}) {
  validateConfig(config);
  if (availabilityDirectory !== undefined) validateAvailabilityDirectory(availabilityDirectory);
  const totalTimeout = validateRequestTimeout(requestTimeoutMs ?? config.requestTimeoutMs ?? DEFAULT_REQUEST_TIMEOUT_MS);
  if (!Number.isInteger(port) || port < 0 || port > 65535) throw new RangeError('port must be 0–65535');
  if (!object(handlers) || nativeFactory !== null && typeof nativeFactory !== 'function') {
    throw new TypeError('Invalid handler map or nativeFactory');
  }
  for (const route of config.routes) {
    if (route.handler && (!OWN(handlers, route.handler) || typeof handlers[route.handler] !== 'function')) {
      throw new TypeError(`Application handler export missing: ${route.handler}`);
    }
    if (route.admit && (!OWN(handlers, route.admit) || typeof handlers[route.admit] !== 'function')) {
      throw new TypeError(`Admission export missing: ${route.admit}`);
    }
  }
  const { assets, retainedBytes, maxResponseBytes } = await prepareResponseAssets(config);
  const admissions = new Map(config.routes.map(route => {
    const application = createConfiguredAdmission(route, handlers);
    return [route.id, assets.has(route.id) ? composeAssetAdmission(application) : application];
  }));
  const inputValidation = new Set(config.routes.filter(route => route.validateInput === true).map(route => route.id));
  const fileResponses = new Map();
  for (const route of config.routes) {
    if (!OWN(route, 'responseFile')) continue;
    try {
      fileResponses.set(route.id, (await readJsonResponseFile(route.responseFile)).body);
    } catch (error) {
      throw new Error(`Route ${route.id} responseFile: ${error.message}`, { cause: error });
    }
  }
  let dispatch = (_req, res) => { res.writeHead(503, { 'retry-after': '1' }); res.end(); };
  const server = createServer((req, res) => {
    return Promise.resolve().then(() => dispatch(req, res)).catch(() => {
      if (!res.headersSent) res.writeHead(500, { 'content-type': 'application/json', 'cache-control': 'no-store' });
      if (!res.writableEnded) res.end('{"error":"SELLER_REQUEST_FAILED"}');
    });
  });
  server.requestTimeout = 15000;
  server.headersTimeout = 10000;
  server.keepAliveTimeout = 5000;
  const lifecycle = createSellerLifecycle(server, { maxInFlight, drainGraceMs });
  let availability, closing;
  const close = () => closing ??= (async () => {
    const result = await lifecycle.close();
    // Keep the private writer lease while original native work drains. A forced
    // drain failure retains it until process exit.
    await availability?.close();
    return result;
  })();
  try {
    await new Promise((done, fail) => { server.once('error', fail); server.listen(port, HOST, done); });
    const url = `http://${HOST}:${server.address().port}`;
    const origin = config.publicOrigin ? new URL(config.publicOrigin).origin : url;
    const compiled = compileSellerRoutes(config.routes.map(route => ({
      id: route.id,
      maxRequestBytes:route.maxRequestBytes,
      ...(admissions.get(route.id) ? { admit: admissions.get(route.id) } : {}),
      ...(assets.has(route.id) ? { offer: compileAssetRouteOffer(route, origin,
        compileHttpSellerOffer, !config.publicOrigin) } :
        route.offer ? { offer: route.offer } : { definition: { ...route.definition, url: origin + route.path } }),
      handler: assets.has(route.id) ? assets.get(route.id).handler : route.handler ? handlers[route.handler] : async () => ({
        status: 200, headers: { 'content-type': 'application/json' },
        body: fileResponses.has(route.id) ? Buffer.from(fileResponses.get(route.id)) : structuredClone(route.response),
      }),
    })), { allowLocalhost: !config.publicOrigin });
    if (availabilityDirectory !== undefined)
      availability = await createSellerAvailability(compiled, availabilityDirectory);
    const nativeServer = nativeFactory ? await nativeFactory(compiled) : null;
    if (nativeFactory && !nativeServer) throw new TypeError('Native factory did not return a resource server');
    const resources = createSellerResourceHandler({ compiled, nativeServer, maxResponseBytes,
      maxRequestBytes: config.maxRequestBytes ?? 1048576,
      maxStreamBytes: config.maxStreamBytes,
      admissionTimeoutMs: config.admissionTimeoutMs ?? 2000,
      handlerTimeoutMs: config.handlerTimeoutMs ?? 30000, requestTimeoutMs: totalTimeout });
    const mode = nativeServer ? 'NATIVE_X402' : 'CHALLENGE_ONLY';
    const developerPortal = createSellerDeveloperPortal({ compiled, mode });
    const info = { schema: SCHEMA, mode,
      ...(assets.size ? { assetSnapshotBytes: retainedBytes, maxResponseBytes } : {}),
      routes: compiled.routes.map(route => ({
      id: route.id, method: route.method, url: route.offer.resource.url,
      admission: typeof route.admit === 'function',
      inputValidation: inputValidation.has(route.id),
      ...(assets.has(route.id) ? { asset: assets.get(route.id).metadata } : {}),
      ...(route.binding.dynamic ? { routeTemplate: route.path } : {}),
    })) };
    dispatch = (req, res) => {
      if (developerPortal(req, res)) return;
      if (req.url === '/_seller/ready') {
        if (!['GET', 'HEAD'].includes(req.method)) {
          res.writeHead(405, { allow: 'GET, HEAD' }); res.end(); return;
        }
        const ready = lifecycle.snapshot();
        const payload = JSON.stringify({ state: ready.state, accepting: ready.accepting });
        res.writeHead(ready.accepting ? 200 : 503, {
          'content-type': 'application/json', 'cache-control': 'no-store',
          'x-content-type-options': 'nosniff', 'content-length': String(Buffer.byteLength(payload)),
        });
        res.end(req.method === 'HEAD' ? undefined : payload);
        return;
      }
      if (req.url === '/_seller/health' || req.url === '/_seller/offers') {
        if (!['GET', 'HEAD'].includes(req.method)) { res.writeHead(405, { allow: 'GET, HEAD' }); res.end(); return; }
        const payload = req.url === '/_seller/health' ?
          { ...info, lifecycle: lifecycle.snapshot(), requestLifetime: resources.lifetimeSnapshot() } : compiled.routes.map(route => route.offer);
        res.writeHead(200, { 'content-type': 'application/json', 'cache-control': 'no-store',
          'x-content-type-options': 'nosniff' });
        res.end(req.method === 'HEAD' ? '' : JSON.stringify(payload));
        return;
      }
      return lifecycle.handle(req, res, () => availability
        ? availability.handle(req, res, () => resources(req, res)) : resources(req, res));
    };
    return { server, url, mode, compiled, lifecycle, close, ...(availability ? { availability } : {}) };
  } catch (error) {
    if (server.listening) await close();
    else await availability?.close();
    throw error;
  }
}

export async function main(args = process.argv.slice(2)) {
  if (args.length === 1 && args[0] === '--help') { process.stdout.write(USAGE + '\n'); return null; }
  const options = new Map();
  for (let i = 0; i < args.length; i++) {
    const flag = args[i];
    if (options.has(flag)) throw new TypeError('Duplicate option: ' + flag);
    if (flag === '--allow-local-facilitator') { options.set(flag, true); continue; }
    if (!['--config', '--port', '--handlers', '--facilitator', '--max-in-flight', '--drain-grace-ms', '--request-timeout-ms', '--availability-dir'].includes(flag) || !args[i + 1] || args[i + 1].startsWith('--')) {
      throw new TypeError(USAGE);
    }
    options.set(flag, args[++i]);
  }
  if (!options.has('--config') || options.has('--allow-local-facilitator') && !options.has('--facilitator')) throw new TypeError(USAGE);
  const configPath = resolve(options.get('--config'));
  const config = await readSellerConfig(configPath);
  const portText = options.get('--port') ?? '8423';
  if (!/^\d{1,5}$/.test(portText)) throw new TypeError('port must be 0–65535');
  const handlers = options.has('--handlers') ?
    await import(pathToFileURL(resolve(dirname(configPath), options.get('--handlers'))).href) : {};
  let nativeFactory = null;
  if (options.has('--facilitator')) {
    const url = facilitatorEndpoint(options.get('--facilitator'), options.get('--allow-local-facilitator'));
    const [{ HTTPFacilitatorClient }, { createNativeSellerServer }] = await Promise.all([
      import('@x402/core/server'), import('./native-factory.mjs'),
    ]);
    nativeFactory = compiled => createNativeSellerServer(compiled, {
      facilitatorClient: new HTTPFacilitatorClient({ url }),
    });
  }
  const session = await startSellerService({ config, port: Number(portText), handlers, nativeFactory,
    availabilityDirectory: options.get('--availability-dir'),
    ...(options.has('--request-timeout-ms') ? { requestTimeoutMs: validateRequestTimeout(Number(options.get('--request-timeout-ms'))) } : {}),
    maxInFlight: Number(options.get('--max-in-flight') ?? 64),
    drainGraceMs: Number(options.get('--drain-grace-ms') ?? 60000) });
  process.stdout.write(JSON.stringify({ url: session.url, mode: session.mode,
    health: session.url + '/_seller/health', ready: session.url + '/_seller/ready',
    offers: session.url + '/_seller/offers',
    docs: session.url + '/_seller/docs', openapi: session.url + '/_seller/openapi.json' }) + '\n');
  for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, () => {
    session.close().then(() => { process.exitCode = 0; }, () => { process.exitCode = 1; });
  });
  return session;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch(error => { process.stderr.write(String(error?.message ?? error) + '\n'); process.exitCode = 1; });
}

#!/usr/bin/env python3
"""Streaming source archives shared by the original Cloud and SF49 receivers.

Extracted from duckdb/cloud-delivery/native.py (ca718b77e409136be6ccb94a7c134988d2f22233).
The caller supplies its own schema and limits; source bytes and their inventories
keep their original identity. Only the Python standard library is required.
"""
from __future__ import annotations
from contextlib import contextmanager
import hashlib
import json
import os
from pathlib import Path
import re
import sqlite3
import stat
import zipfile
import zlib

CHUNK = 1024 * 1024


class ArchiveFault(Exception):
    def __init__(self, code, message=None):
        super().__init__(message or code)
        self.code, self.message = code, message or code


class ArchivePolicy:
    def __init__(self, schema, *, max_expanded_bytes, max_members=20000,
                 max_manifest_bytes=32 * CHUNK, max_file_bytes=None, receipt_name="received-handover.json",
                 prefix="SOURCE_ARCHIVE", error_type=ArchiveFault):
        if not isinstance(schema, str) or not schema or not re.fullmatch(r"[A-Z][A-Z0-9_]*", prefix):
            raise ValueError("An explicit archive schema and error prefix are required")
        for value in (max_expanded_bytes, max_members, max_manifest_bytes):
            if type(value) is not int or value < 1:
                raise ValueError("Positive archive limits are required")
        if receipt_name is not None and (not isinstance(receipt_name, str) or
                not receipt_name or "/" in receipt_name or "\\" in receipt_name or
                receipt_name in (".", "..") or "\x00" in receipt_name):
            raise ValueError("Use a receipt basename")
        self.schema = schema
        if max_file_bytes is not None and (type(max_file_bytes) is not int or max_file_bytes < 1):
            raise ValueError("A positive per-file limit is required")
        self.max_file_bytes = max_expanded_bytes if max_file_bytes is None else max_file_bytes
        self.max_expanded_bytes = max_expanded_bytes
        self.max_archive_bytes = max_expanded_bytes + 16 * CHUNK
        self.max_members = max_members
        self.max_manifest_bytes = max_manifest_bytes
        self.receipt_name = receipt_name
        self.prefix, self.error_type = prefix, error_type

    def fail(self, code, message=None):
        raise self.error_type(self.prefix + "_" + code, message)


def encoded(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False,
                      separators=(",", ":"), sort_keys=True)


def _json(raw, policy):
    def pairs(values):
        result = {}
        for key, value in values:
            if key in result:
                policy.fail("HANDOVER_MANIFEST_INVALID")
            result[key] = value
        return result
    try:
        return json.loads(raw.decode("utf-8"), object_pairs_hook=pairs,
                          parse_constant=lambda _v: policy.fail("HANDOVER_MANIFEST_INVALID"))
    except (ValueError, UnicodeError):
        policy.fail("HANDOVER_MANIFEST_INVALID")


def _relative(name, policy):
    if not isinstance(name, str) or not name or name.startswith("/") or "\\" in name or "\x00" in name or any(
            part in ("", ".", "..") for part in name.split("/")):
        policy.fail("HANDOVER_PATH_INVALID")
    if name.split("/")[0].startswith(".source-archive-"):
        policy.fail("HANDOVER_PATH_INVALID")
    return name


def _path(root, name, policy):
    target = root / _relative(name, policy)
    if target.resolve() != target or not target.is_relative_to(root):
        policy.fail("HANDOVER_PATH_INVALID")
    return target


def _directory(value, policy, *, create=False):
    root = Path(value)
    if not root.is_absolute() or root.resolve() != root:
        policy.fail("HANDOVER_PATH_INVALID")
    if create:
        missing, parent = [], root
        while not parent.exists():
            missing.append(parent)
            parent = parent.parent
        for directory in reversed(missing):
            try:
                directory.mkdir(mode=0o700)
            except FileExistsError:
                pass
            info = directory.lstat()
            if not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode):
                policy.fail("HANDOVER_PATH_INVALID")
    info = root.lstat()
    if not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode):
        policy.fail("HANDOVER_PATH_INVALID")
    return root



def private_directories(root, target, *, policy):
    """Create or reconcile only directories beneath the caller's owned root.

    Archive extraction calls this after its exact request is retained under the
    original lease. Other callers must establish that same ownership themselves.
    Existing ancestors outside root are never changed.
    """
    root = _directory(root, policy)
    target = Path(target)
    if not target.is_absolute() or target.resolve() != target or not target.is_relative_to(root):
        policy.fail("HANDOVER_PATH_INVALID")
    current = root
    for part in target.relative_to(root).parts:
        parent = current
        current = current / part
        created = False
        try:
            current.mkdir(mode=0o700)
            created = True
        except FileExistsError:
            pass
        fd = os.open(current, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) |
                     getattr(os, "O_NOFOLLOW", 0))
        try:
            info = os.fstat(fd)
            if not stat.S_ISDIR(info.st_mode):
                policy.fail("HANDOVER_PATH_INVALID")
            if stat.S_IMODE(info.st_mode) != 0o700:
                os.fchmod(fd, 0o700)
                os.fsync(fd)
            if created:
                _sync(parent)
        finally:
            os.close(fd)
    return target


def _sync(root):
    fd = os.open(root, os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def file_hash(value, policy, *, maximum=None):
    path = Path(value)
    fd = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        before = os.fstat(fd)
        maximum = policy.max_expanded_bytes if maximum is None else maximum
        if not stat.S_ISREG(before.st_mode) or before.st_size > maximum:
            policy.fail("REGULAR_FILE_REQUIRED")
        checksum, size = hashlib.sha256(), 0
        with os.fdopen(fd, "rb", closefd=False) as handle:
            for chunk in iter(lambda: handle.read(CHUNK), b""):
                size += len(chunk)
                if size > maximum or size > before.st_size:
                    policy.fail("ORIGINAL_FILE_CHANGED")
                checksum.update(chunk)
        after = os.fstat(fd)
        current = path.lstat()
        fields = ("st_dev", "st_ino", "st_size", "st_mtime_ns", "st_ctime_ns")
        if size != before.st_size or any(getattr(before, key) != getattr(after, key) for key in fields) or (
                current.st_dev, current.st_ino) != (before.st_dev, before.st_ino) or stat.S_ISLNK(current.st_mode):
            policy.fail("ORIGINAL_FILE_CHANGED")
        return {"bytes": str(size), "sha256": checksum.hexdigest()}
    finally:
        os.close(fd)


def _pin(file, policy):
    if not isinstance(file, dict):
        policy.fail("HANDOVER_INVENTORY_MISMATCH")
    _relative(file.get("path"), policy)
    size, digest = file.get("bytes"), file.get("sha256")
    if not isinstance(size, str) or not re.fullmatch(r"0|[1-9][0-9]{0,15}", size) or (
            int(size) > policy.max_file_bytes) or not isinstance(digest, str) or not re.fullmatch(r"[a-f0-9]{64}", digest):
        policy.fail("HANDOVER_FILE_INVALID")
    return {"bytes": size, "sha256": digest}


def _manifest(manifest, policy):
    if not isinstance(manifest, dict) or manifest.get("schema") != policy.schema:
        policy.fail("HANDOVER_SCHEMA_INVALID")
    raw = (encoded(manifest) + "\n").encode("utf-8")
    if len(raw) > policy.max_manifest_bytes:
        policy.fail("HANDOVER_MANIFEST_INVALID")
    files = manifest.get("files")
    if not isinstance(files, list) or len(files) + 1 > policy.max_members:
        policy.fail("HANDOVER_INVENTORY_MISMATCH")
    names, total = set(), len(raw)
    for file in files:
        pin = _pin(file, policy)
        name = file["path"]
        if name in names or (policy.receipt_name is not None and name == policy.receipt_name):
            policy.fail("HANDOVER_INVENTORY_MISMATCH")
        names.add(name)
        total += int(pin["bytes"])
        if total > policy.max_expanded_bytes:
            policy.fail("HANDOVER_SIZE_LIMIT")
    return files, raw


@contextmanager
def _owner(root, name, policy):
    key = hashlib.sha256(name.encode("utf-8")).hexdigest()
    path = root / (".source-archive-" + key + ".sqlite")
    fd = os.open(path, os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0), 0o600)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_mode & 0o077:
            policy.fail("HANDOVER_PATH_INVALID")
    finally:
        os.close(fd)
    owner = sqlite3.connect(path, timeout=0)
    try:
        try:
            owner.execute("BEGIN EXCLUSIVE")
        except sqlite3.OperationalError as error:
            if (getattr(error, "sqlite_errorcode", 0) & 0xff) not in (sqlite3.SQLITE_BUSY, sqlite3.SQLITE_LOCKED):
                raise
            raise policy.error_type(policy.prefix + "_HANDOVER_ALREADY_RUNNING",
                                    "The original archive destination has an active writer.") from error
        yield
    finally:
        owner.close()


def _stage(path, digest, *, root=None):
    # A source filename must never be mistaken for one of our recovery files.
    # Extraction supplies its root so even nested source paths use the reserved
    # top-level namespace, which _relative() excludes from every inventory.
    root = path.parent if root is None else root
    identity = str(path.relative_to(root)).encode("utf-8") + b"\x00" + digest.encode("ascii")
    return root / (".source-archive-stage-" + hashlib.sha256(identity).hexdigest() + ".partial")


def _remove_stage(path, policy):
    try:
        info = path.lstat()
    except FileNotFoundError:
        return
    if not stat.S_ISREG(info.st_mode) or stat.S_ISLNK(info.st_mode):
        policy.fail("HANDOVER_PATH_INVALID")
    path.unlink()


def _reconcile_published_stage(path, temporary, policy):
    """Retire only the verified destination's own surviving hard-link stage.

    The caller has already verified the final file against its expected bytes.
    A different inode is independent custody and remains untouched.
    """
    try:
        final, staged = path.lstat(), temporary.lstat()
    except FileNotFoundError:
        return
    if (final.st_dev, final.st_ino) != (staged.st_dev, staged.st_ino):
        return
    if (not stat.S_ISREG(final.st_mode) or not stat.S_ISREG(staged.st_mode) or
            final.st_nlink != 2 or staged.st_nlink != 2 or
            final.st_mode & 0o077 or staged.st_mode & 0o077):
        policy.fail("HANDOVER_PATH_INVALID")
    # Make the final name durable before removing its verified original stage.
    _sync(path.parent)
    temporary.unlink()
    _sync(temporary.parent)


def _publish(path, temporary, pin, policy):
    try:
        os.link(temporary, path, follow_symlinks=False)
    except FileExistsError:
        if file_hash(path, policy, maximum=policy.max_archive_bytes) != pin:
            policy.fail("RECEIVED_FILE_CONFLICT")
    _sync(path.parent)
    temporary.unlink(missing_ok=True)
    if temporary.parent != path.parent:
        _sync(temporary.parent)


def _retain_metadata(path, raw, policy):
    pin = {"bytes": str(len(raw)), "sha256": hashlib.sha256(raw).hexdigest()}
    temporary = _stage(path, pin["sha256"])
    if path.exists():
        if file_hash(path, policy, maximum=policy.max_manifest_bytes) != pin:
            policy.fail("HANDOVER_SNAPSHOT_CONFLICT")
        _reconcile_published_stage(path, temporary, policy)
        return
    if temporary.exists():
        try:
            ready = file_hash(temporary, policy, maximum=policy.max_manifest_bytes) == pin
        except policy.error_type:
            ready = False
        if ready:
            _publish(path, temporary, pin, policy)
            return
        _remove_stage(temporary, policy)
    fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
    try:
        with os.fdopen(fd, "wb", closefd=False) as handle:
            handle.write(raw)
            handle.flush()
            os.fsync(handle.fileno())
        _publish(path, temporary, pin, policy)
    finally:
        os.close(fd)


def _read_zip(bundle, policy, expected=None):
    members = bundle.infolist()
    if len(members) > policy.max_members or sum(item.file_size for item in members) > policy.max_expanded_bytes:
        policy.fail("HANDOVER_SIZE_LIMIT")
    names = [item.filename for item in members]
    if len(set(names)) != len(names) or "handover.json" not in names or (
            bundle.getinfo("handover.json").file_size > policy.max_manifest_bytes):
        policy.fail("HANDOVER_MANIFEST_INVALID")
    for item in members:
        kind = (item.external_attr >> 16) & 0o170000
        if kind not in (0, stat.S_IFREG) or item.flag_bits & 1 or (
                item.compress_type not in (zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED)):
            policy.fail("HANDOVER_FILE_INVALID")
    manifest = _json(bundle.read("handover.json"), policy)
    files, raw = _manifest(manifest, policy)
    if expected is not None and encoded(manifest) != encoded(expected):
        policy.fail("HANDOVER_SNAPSHOT_CONFLICT")
    if set(names) != {"handover.json"} | {"files/" + file["path"] for file in files}:
        policy.fail("HANDOVER_INVENTORY_MISMATCH")
    for file in files:
        if str(bundle.getinfo("files/" + file["path"]).file_size) != file["bytes"]:
            policy.fail("HANDOVER_FILE_SIZE_MISMATCH")
    return manifest, files, raw


def _verify_member(bundle, file, policy):
    checksum, size = hashlib.sha256(), 0
    with bundle.open("files/" + file["path"]) as member:
        for chunk in iter(lambda: member.read(CHUNK), b""):
            checksum.update(chunk)
            size += len(chunk)
            if size > int(file["bytes"]):
                policy.fail("HANDOVER_FILE_SIZE_MISMATCH")
    if str(size) != file["bytes"] or checksum.hexdigest() != file["sha256"]:
        policy.fail("HANDOVER_FILE_DIGEST_MISMATCH")


def _verify_zip(path, policy, expected=None):
    before = file_hash(path, policy, maximum=policy.max_archive_bytes)
    with zipfile.ZipFile(path) as bundle:
        manifest, files, _raw = _read_zip(bundle, policy, expected)
        for file in files:
            _verify_member(bundle, file, policy)
    if before != file_hash(path, policy, maximum=policy.max_archive_bytes):
        policy.fail("HANDOVER_SOURCE_CHANGED")
    return {"archive": before, "members": len(files) + 1}, manifest


def inspect(input, *, policy):
    result, manifest = _verify_zip(Path(input["archive"]), policy)
    return {**result, "manifest": manifest}


def archive(input, *, policy):
    manifest = input["manifest"]
    files, raw = _manifest(manifest, policy)
    if encoded(files) != encoded(input["inventory"]):
        policy.fail("HANDOVER_INVENTORY_MISMATCH")
    output = Path(input["destination"])
    root = _directory(output.parent, policy)
    if output.resolve() != output:
        policy.fail("HANDOVER_PATH_INVALID")
    key = hashlib.sha256(raw).hexdigest()
    with _owner(root, output.name, policy):
        _retain_metadata(root / (".source-archive-" + hashlib.sha256(output.name.encode()).hexdigest() + ".request.json"),
                         (encoded({"manifestSha256": key, "schema": policy.schema}) + "\n").encode(), policy)
        temporary = _stage(output, key)
        if output.exists():
            result, _manifest_value = _verify_zip(output, policy, manifest)
            _reconcile_published_stage(output, temporary, policy)
            return {**result, "reused": True}
        if temporary.exists():
            try:
                result, _manifest_value = _verify_zip(temporary, policy, manifest)
            except (policy.error_type, zipfile.BadZipFile, EOFError, RuntimeError, zlib.error):
                _remove_stage(temporary, policy)
            else:
                _publish(output, temporary, result["archive"], policy)
                return {**result, "reused": True, "reconciled": True}
        source = _directory(input["source"], policy)
        fd = os.open(temporary, os.O_RDWR | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
        try:
            with os.fdopen(fd, "w+b", closefd=False) as stream:
                with zipfile.ZipFile(stream, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6) as bundle:
                    bundle.writestr("handover.json", raw)
                    for file in files:
                        original_path = _path(source, file["path"], policy)
                        before = file_hash(original_path, policy)
                        if before != _pin(file, policy):
                            policy.fail("HANDOVER_SOURCE_CHANGED")
                        checksum, size = hashlib.sha256(), 0
                        input_fd = os.open(original_path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
                        try:
                            with os.fdopen(input_fd, "rb", closefd=False) as original, bundle.open(
                                    "files/" + file["path"], "w", force_zip64=True) as target:
                                for chunk in iter(lambda: original.read(CHUNK), b""):
                                    size += len(chunk)
                                    if size > int(file["bytes"]):
                                        policy.fail("HANDOVER_SOURCE_CHANGED")
                                    checksum.update(chunk)
                                    target.write(chunk)
                        finally:
                            os.close(input_fd)
                        if str(size) != file["bytes"] or checksum.hexdigest() != file["sha256"] or file_hash(original_path, policy) != before:
                            policy.fail("HANDOVER_SOURCE_CHANGED")
                stream.flush()
                os.fsync(stream.fileno())
            pin = file_hash(temporary, policy, maximum=policy.max_archive_bytes)
            _publish(output, temporary, pin, policy)
            return {"archive": pin, "members": len(files) + 1}
        except BaseException:
            # This exact manifest-bound stage belongs to the held destination
            # lease. Process death leaves it for the same request to reconcile.
            _remove_stage(temporary, policy)
            raise
        finally:
            os.close(fd)


def extract(input, *, policy):
    source = Path(input["archive"])
    before = file_hash(source, policy, maximum=policy.max_archive_bytes)
    destination = _directory(input["destination"], policy, create=True)
    with _owner(destination, "extract", policy):
        with zipfile.ZipFile(source) as bundle:
            manifest, files, raw = _read_zip(bundle, policy)
            _retain_metadata(destination / ".source-archive-request.json",
                             (encoded({"archive": before, "manifestSha256": hashlib.sha256(raw).hexdigest(),
                                       "schema": policy.schema}) + "\n").encode(), policy)
            receipt = destination / policy.receipt_name if policy.receipt_name is not None else None
            if receipt is not None and receipt.exists():
                if file_hash(receipt, policy, maximum=policy.max_manifest_bytes) != {
                        "bytes": str(len(raw)), "sha256": hashlib.sha256(raw).hexdigest()}:
                    policy.fail("HANDOVER_SNAPSHOT_CONFLICT")
            for file in files:
                target = _path(destination, file["path"], policy)
                private_directories(destination, target.parent, policy=policy)
                _path(destination, file["path"], policy)
                expected = _pin(file, policy)
                temporary = _stage(target, file["sha256"], root=destination)
                if target.exists():
                    # Reusing a correct output is not evidence that this ZIP
                    # carries those bytes. Read it through CRC and SHA checks.
                    _verify_member(bundle, file, policy)
                    if file_hash(target, policy) != expected:
                        policy.fail("RECEIVED_FILE_CONFLICT")
                    _reconcile_published_stage(target, temporary, policy)
                    continue
                if temporary.exists():
                    try:
                        ready = file_hash(temporary, policy) == expected
                    except policy.error_type:
                        ready = False
                    if ready:
                        _verify_member(bundle, file, policy)
                        if file_hash(temporary, policy) != expected:
                            policy.fail("ORIGINAL_FILE_CHANGED")
                        _publish(target, temporary, expected, policy)
                        continue
                    _remove_stage(temporary, policy)
                fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
                try:
                    checksum, size = hashlib.sha256(), 0
                    with bundle.open("files/" + file["path"]) as original, os.fdopen(fd, "wb", closefd=False) as retained:
                        for chunk in iter(lambda: original.read(CHUNK), b""):
                            size += len(chunk)
                            if size > int(file["bytes"]):
                                policy.fail("HANDOVER_FILE_SIZE_MISMATCH")
                            checksum.update(chunk)
                            retained.write(chunk)
                        retained.flush()
                        os.fsync(retained.fileno())
                    if str(size) != file["bytes"] or checksum.hexdigest() != file["sha256"]:
                        policy.fail("HANDOVER_FILE_DIGEST_MISMATCH")
                    _publish(target, temporary, expected, policy)
                except BaseException:
                    _remove_stage(temporary, policy)
                    raise
                finally:
                    os.close(fd)
        if before != file_hash(source, policy, maximum=policy.max_archive_bytes):
            policy.fail("HANDOVER_SOURCE_CHANGED")
        if receipt is not None:
            _retain_metadata(receipt, raw, policy)
    return {"manifest": manifest, "archive": before}

"""Lossless source-file restoration from original SF88 or finalized SF100 delivery.

Providers supply manifest and release validators. Original DatasetDelivery owns
page, recovery, accounting and transport state; this module reconstructs bytes.
"""
from __future__ import annotations

import base64
import binascii
from dataclasses import dataclass
import hashlib
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import stat
import tempfile
from typing import Callable, ClassVar

CHUNK_BYTES = 49_152
COMMON_FIELDS = frozenset({
    "capture_id", "path", "file_sha256", "file_bytes", "chunk_index",
    "chunk_count", "chunk_sha256", "content_base64",
})
_SHA256 = re.compile(r"[0-9a-f]{64}\Z")


class SourceFileDeliveryError(ValueError):
    def __init__(self, code: str, **details):
        self.code, self.details = code, details
        super().__init__(code)


@dataclass(frozen=True)
class SourceFileContract:
    manifest_path: str
    manifest_schema: str
    prefix: str
    error_type: type
    required_fields: frozenset
    row_identity: Callable
    validate_manifest: Callable
    staging_prefix: str = ".source-receive-"

    def fail(self, code, **details):
        raise self.error_type(self.prefix + "_" + code, **details)

    def name(self, value) -> str:
        if (not isinstance(value, str) or not value or "\\" in value
                or "\x00" in value or PurePosixPath(value).is_absolute()
                or any(part in ("", ".", "..") for part in value.split("/"))):
            self.fail("SOURCE_PATH_INVALID")
        return value

    def sha(self, value, field) -> str:
        if not isinstance(value, str) or not _SHA256.fullmatch(value):
            self.fail("SHA256_INVALID", field=field)
        return value

    def integer(self, value, field, minimum=0) -> int:
        if type(value) is not int or value < minimum:
            self.fail("INTEGER_INVALID", field=field)
        return value


def read_member(directory: Path, member: dict, contract: SourceFileContract, *, collect=False):
    """Check identity, permission, length and digest on the same opened file."""
    name = contract.name(member["path"])
    path = directory / name
    try:
        if path.resolve(strict=True) != path or directory not in path.parents:
            contract.fail("SOURCE_PATH_CHANGED", path=name)
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if (not stat.S_ISREG(info.st_mode) or info.st_nlink != 1
                    or info.st_mode & 0o077 or info.st_size != member["bytes"]):
                contract.fail("SOURCE_FILE_CHANGED", path=name)
            digest, size = hashlib.sha256(), 0
            chunks = [] if collect else None
            while raw := stream.read(1_048_576):
                size += len(raw)
                digest.update(raw)
                if collect:
                    chunks.append(raw)
        if size != member["bytes"] or digest.hexdigest() != member["sha256"]:
            contract.fail("SOURCE_FILE_CHANGED", path=name)
        return b"".join(chunks) if collect else None
    except OSError:
        contract.fail("SOURCE_FILE_UNAVAILABLE", path=name)


@dataclass(frozen=True)
class SourceFiles:
    directory: Path
    capture_id: str
    manifest: dict
    native_status: str
    payment_status: str
    acquired_rows: int
    reopened: bool
    contract: ClassVar[SourceFileContract]

    def member(self, name: str) -> dict:
        name = self.contract.name(name)
        for item in self.manifest["files"]:
            if item["path"] == name:
                return dict(item)
        self.contract.fail("SOURCE_MEMBER_UNDECLARED", path=name)

    def read_file(self, name: str) -> bytes:
        return read_member(self.directory, self.member(name), self.contract, collect=True)

    def source_path(self, name: str) -> Path:
        read_member(self.directory, self.member(name), self.contract)
        return self.directory / name


def _row(row, contract):
    if not isinstance(row, dict) or not contract.required_fields <= row.keys():
        contract.fail("SOURCE_FILES_PROJECTION_REQUIRED")
    identity = contract.row_identity(row, contract)
    capture_id = contract.sha(row["capture_id"], "capture_id")
    name = contract.name(row["path"])
    size = contract.integer(row["file_bytes"], "file_bytes")
    count = contract.integer(row["chunk_count"], "chunk_count", 1)
    index = contract.integer(row["chunk_index"], "chunk_index")
    if count != max(1, (size + CHUNK_BYTES - 1) // CHUNK_BYTES) or index >= count:
        contract.fail("CHUNK_GEOMETRY_INVALID", path=name)
    encoded = row["content_base64"]
    if not isinstance(encoded, str) or len(encoded) > 65_536:
        contract.fail("CHUNK_ENCODING_INVALID", path=name)
    try:
        raw = base64.b64decode(encoded, validate=True)
    except (ValueError, UnicodeError, binascii.Error):
        contract.fail("CHUNK_ENCODING_INVALID", path=name)
    if (len(raw) != min(CHUNK_BYTES, size - index * CHUNK_BYTES)
            or base64.b64encode(raw).decode("ascii") != encoded):
        contract.fail("CHUNK_SIZE_INVALID", path=name)
    if hashlib.sha256(raw).hexdigest() != contract.sha(row["chunk_sha256"], "chunk_sha256"):
        contract.fail("CHUNK_HASH_MISMATCH", path=name, chunk=index)
    item = {"path": name, "bytes": size,
            "sha256": contract.sha(row["file_sha256"], "file_sha256"), "chunks": count}
    return (capture_id, identity), item, index, raw


def _manifest(raw, identity, restored, contract):
    from stellar_forge_buyer.storage import parse

    if hashlib.sha256(raw).hexdigest() != identity[0]:
        contract.fail("CAPTURE_ID_MISMATCH")
    value = parse(raw)
    if not isinstance(value, dict) or value.get("schema") != contract.manifest_schema:
        contract.fail("CAPTURE_MANIFEST_INVALID")
    members = value.get("files")
    if not isinstance(members, list) or not members:
        contract.fail("CAPTURE_FILES_INVALID")
    expected = {}
    for item in members:
        if not isinstance(item, dict):
            contract.fail("CAPTURE_FILES_INVALID")
        name = contract.name(item.get("path"))
        if name == contract.manifest_path or name in expected:
            contract.fail("CAPTURE_DUPLICATE_PATH", path=name)
        expected[name] = {
            "path": name, "bytes": contract.integer(item.get("bytes"), "bytes"),
            "sha256": contract.sha(item.get("sha256"), "sha256")}
    actual_names = set(restored) - {contract.manifest_path}
    if set(expected) != actual_names:
        contract.fail("CAPTURE_FILE_INVENTORY_MISMATCH",
            missing=sorted(set(expected) - actual_names),
            unexpected=sorted(actual_names - set(expected)))
    for name, item in expected.items():
        actual = restored[name]["item"]
        if any(actual[field] != item[field] for field in ("path", "bytes", "sha256")):
            contract.fail("CAPTURE_FILE_METADATA_MISMATCH", path=name)
    contract.validate_manifest(value, identity[1], expected, contract)
    return value


def restore_file_projection(delivery, destination, *, result_type,
                            expected_capture_id=None, check_identity=None):
    """Restore one complete acquired inventory and reopen matching output.

    Chunks for a file arrive in ascending order; different files may interleave.
    The manifest must enumerate every acquired member except itself.
    """
    from stellar_forge_buyer.storage import private_directory, sync_directory

    contract = result_type.contract
    if expected_capture_id is not None:
        contract.sha(expected_capture_id, "expected_capture_id")
    native = delivery.native
    if (not isinstance(native, dict) or native.get("schema") not in {
            "stellar-forge.sf88.dataset-delivery.v1",
            "stellar-forge.sf100.dataset-delivery.v1"}
            or native.get("schema") == "stellar-forge.sf100.dataset-delivery.v1"
            and native.get("sourceFormat") != "SF100_SCAN"):
        raise contract.error_type("ORIGINAL_DATASET_DELIVERY_REQUIRED")
    output = Path(os.path.abspath(Path(destination).expanduser()))
    parent = private_directory(output.parent)
    if parent != output.parent:
        contract.fail("OUTPUT_CANONICAL_PATH_REQUIRED")
    staging = Path(tempfile.mkdtemp(prefix=contract.staging_prefix, dir=parent))
    states, identity, row_count = {}, None, 0
    try:
        for row in delivery.jsonl_rows():
            row_identity, item, index, raw = _row(row, contract)
            if identity is None:
                identity = row_identity
                if expected_capture_id is not None and identity[0] != expected_capture_id:
                    contract.fail("CAPTURE_ID_MISMATCH")
                if check_identity:
                    check_identity(identity[1])
            elif row_identity != identity:
                contract.fail("CAPTURE_MIXED_IDENTITIES")
            name = item["path"]
            state = states.get(name)
            if state is None:
                state = {"item": item, "next": 0, "bytes": 0, "digest": hashlib.sha256()}
                states[name] = state
            if state["item"] != item or index != state["next"]:
                contract.fail("CHUNK_ORDER_OR_METADATA_MISMATCH", path=name, chunk=index)
            target = staging / name
            target.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
            flags = os.O_WRONLY | os.O_NOFOLLOW
            flags |= os.O_CREAT | os.O_EXCL if index == 0 else os.O_APPEND
            try:
                fd = os.open(target, flags, 0o600)
                with os.fdopen(fd, "wb") as stream:
                    stream.write(raw)
                    stream.flush()
                    if index + 1 == item["chunks"]:
                        os.fsync(stream.fileno())
            except OSError:
                contract.fail("OUTPUT_FILE_FAILED", path=name)
            state["digest"].update(raw)
            state["bytes"] += len(raw)
            state["next"] += 1
            row_count += 1
        if identity is None or contract.manifest_path not in states:
            contract.fail("CAPTURE_MANIFEST_MISSING")
        for name, state in states.items():
            item = state["item"]
            if (state["next"] != item["chunks"] or state["bytes"] != item["bytes"]
                    or state["digest"].hexdigest() != item["sha256"]):
                contract.fail("SOURCE_FILE_INCOMPLETE", path=name)
        manifest_item = states[contract.manifest_path]["item"]
        manifest_raw = read_member(staging, manifest_item, contract, collect=True)
        manifest = _manifest(manifest_raw, identity, states, contract)
        reopened = output.exists() or output.is_symlink()
        if reopened:
            if private_directory(output, create=False) != output:
                contract.fail("OUTPUT_CANONICAL_PATH_REQUIRED")
            if read_member(output, manifest_item, contract, collect=True) != manifest_raw:
                contract.fail("OUTPUT_CAPTURE_CONFLICT")
            for item in manifest["files"]:
                read_member(output, item, contract)
        else:
