  need(['sse', 'ndjson'].includes(format), 'BAD_RESPONSE_STREAM_FORMAT');
  need(Number.isSafeInteger(maxRecordBytes) && maxRecordBytes > 0 && maxRecordBytes <= LIMIT,
    'BAD_RESPONSE_STREAM_RECORD_LIMIT');
