    transfer.amount === expectedPayment.amount;
}

export function gateNextAction(failure, {ledgerReceipt, expectedPayment, explicitNewAuthorization = false} = {}) {
  if (!failure || failure.version !== VERSION) throw new TypeError('unrecognized failure envelope');
  if (failure.settlementMayBePending) {
    const transaction = failure.settlement?.transaction;
    const network = failure.settlement?.network;
    const settled = Boolean(transaction && network && ledgerReceipt?.confirmed === true &&
      ledgerReceipt?.success === true && ledgerReceipt.transaction === transaction && ledgerReceipt.network === network &&
      matchingVerifiedTransfer(ledgerReceipt, expectedPayment));
    return Object.freeze({decision: settled ? 'already_settled' : 'reconcile_before_any_new_payment',
      maySubmitPayment: false, requiresManualReview: !settled});
  }
  if (failure.requiresNewPaymentAuthorization) {
    return Object.freeze({decision: explicitNewAuthorization ? 'prepare_new_authorization' : 'await_user_authorization',
      maySubmitPayment: false, requiresManualReview: !explicitNewAuthorization});
  }
  if (failure.safeToAutoRetry) {
    return Object.freeze({decision: 'retry_read_only_operation', maySubmitPayment: false, requiresManualReview: false});
  }
  return Object.freeze({decision: 'stop_or_request_user_action', maySubmitPayment: false, requiresManualReview: true});
}

// MIT. Read-only x402 Bazaar seller discoverability diagnostic. No wallet, payment or account calls.
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const MAX_JSON_BYTES = 2_000_000;
const MAX_HEADER_BYTES = 64_000;
const URL_LIMIT = 2048;
const HTTP_METHODS = new Set(['GET','HEAD','POST','PUT','PATCH','DELETE']);

export function requireEndpoint(value, {allowLoopback = false} = {}) {
  if (typeof value !== 'string' || value.length > URL_LIMIT) throw new TypeError('Invalid endpoint URL');
  const url = new URL(value);
  if (url.username || url.password || url.hash) throw new TypeError('Credentials and URL fragments are not allowed');
  const loopback = ['127.0.0.1', '[::1]'].includes(url.hostname);
  if (url.protocol !== 'https:' && !(allowLoopback && loopback && url.protocol === 'http:')) {
    throw new TypeError('HTTPS required (local loopback needs --allow-loopback)');
  }
  if (!loopback && /^(localhost|.*\.localhost)$/i.test(url.hostname)) throw new TypeError('Local host not allowed');
  return url;
}

export function resourceKey(value) {
  try {
    // Original BazaarCatalog serializes resource as {url, ...metadata};
    // some external providers return a flat URL string. Accept either
    // without ever coercing an untrusted object into a URL candidate.
    const locator = typeof value === 'string' ? value :
      value !== null && typeof value === 'object' && !Array.isArray(value) &&
      typeof value.url === 'string' ? value.url : null;
    if (locator === null) return null;
    const url = new URL(locator);
    if (!['https:', 'http:'].includes(url.protocol)) return null;
    url.hash = '';
    if (url.pathname.length > 1) url.pathname = url.pathname.replace(/\/+$/, '');
    return url.toString();
  } catch { return null; }
}

export function decodeJsonHeader(value, label = 'header') {
  if (typeof value !== 'string' || value.length > MAX_HEADER_BYTES || !/^[A-Za-z0-9+/_=-]+$/.test(value)) {
    throw new TypeError(`Invalid ${label} encoding`);
  }
  const clean = value.trim().replace(/-/g, '+').replace(/_/g, '/');
  const buffer = Buffer.from(clean, 'base64');
  if (!buffer.length || buffer.length > MAX_HEADER_BYTES ||
      buffer.toString('base64').replace(/=+$/, '') !== clean.replace(/=+$/, '')) {
    throw new TypeError(`Invalid ${label} base64`);
  }
  const decoded = JSON.parse(buffer.toString('utf8'));
  if (!decoded || typeof decoded !== 'object' || Array.isArray(decoded)) throw new TypeError(`Invalid ${label} JSON`);
  return decoded;
}

export function bazaarExtensionOutcome(headerValue) {
  if (!headerValue) return {state: 'NOT_PROVIDED'};
  try {
    const object = decodeJsonHeader(headerValue, 'EXTENSION-RESPONSES');
    const entry = object.bazaar;
    if (!entry || !['success', 'processing', 'rejected'].includes(entry.status)) {
      return {state: 'NO_VALID_BAZAAR_STATUS'};
    }
    return {state: entry.status.toUpperCase(), ...(entry.status === 'rejected' && typeof entry.rejectedReason === 'string'
      ? {reason: entry.rejectedReason.slice(0, 300)} : {})};
  } catch (error) { return {state: 'INVALID_HEADER', error: String(error.message)}; }
}

export function inspectChallenge(status, header) {
  if (status !== 402) return {httpStatus: status, state: status === 200 ? 'UNPAID_GET_HTTP_200' : 'NOT_HTTP_402'};
  if (!header) return {httpStatus: status, state: 'NO_PAYMENT_REQUIRED_HEADER'};
  try {
    const payment = decodeJsonHeader(header, 'PAYMENT-REQUIRED');
    const accepts = Array.isArray(payment.accepts) ? payment.accepts : [];
    const routes = accepts.filter(x => x && typeof x === 'object').slice(0, 40).map(x => ({
      network: typeof x.network === 'string' ? x.network : null,
      scheme: typeof x.scheme === 'string' ? x.scheme : null,
      asset: typeof x.asset === 'string' ? x.asset : null,
      payTo: typeof x.payTo === 'string' ? x.payTo : null,
      amount: typeof x.amount === 'string' ? x.amount : null
    }));
    return {httpStatus: status, state: routes.length ? 'X402_402' : 'INVALID_ACCEPTS',
      x402Version: payment.x402Version ?? null,
      bazaarExtension: Boolean(payment.extensions?.bazaar),
      acceptsCount: accepts.length, accepts: routes};
  } catch (error) {
    return {httpStatus: status, state: 'INVALID_PAYMENT_REQUIRED', error: String(error.message)};
  }
}

// Diagnostic classification only: never attempts payment, settlement, indexing or a paid retry.
export function sellerDiscoveryReadiness(challenge) {
  if (challenge.state === 'CATALOG_NON_GET_ONLY') return {
    state: 'CATALOG_NON_GET_ONLY',
    diagnosis: 'This catalog entry declares only non-GET HTTP operations or MCP tools. No seller-origin GET was made; this is not a failed unpaid payment challenge.',
    nextAction: 'Use the documented method/tool and obtain seller permission before any real payment or invocation. Catalog visibility does not establish live origin readiness.'
  };
  if (challenge.state === 'UNPAID_GET_HTTP_200') return {
    state: 'UNPAID_200_NO_402_DECLARATION',
    diagnosis: 'An unauthenticated GET returned HTTP 200, not a 402 payment declaration. A Bazaar crawler using the same route cannot observe the paid offer from that response.',
    nextAction: 'Check default free-tier, cache, and health-shortcut paths. If discovery requires a paid offer, expose a 402 with Bazaar metadata on the unauthenticated path and make free access explicitly opt-in.'
  };
  if (challenge.state === 'X402_402' && challenge.bazaarExtension) return {
    state: 'UNPAID_402_BAZAAR_VISIBLE',
    diagnosis: 'An unauthenticated 402 with Bazaar metadata is visible. Catalog indexing and any actual settlement remain separate checks.'
  };
  if (challenge.state === 'X402_402') return {
    state: 'UNPAID_402_WITHOUT_BAZAAR',
    diagnosis: 'The HTTP 402 lists payment terms but no Bazaar declaration; a discovery crawler may not have the resource metadata it needs.'
  };
  return {
    state: 'NO_VALID_UNPAID_BAZAAR_402',
    diagnosis: 'A valid unauthenticated HTTP 402 with Bazaar metadata was not observed; inspect the seller response and any fetch or decoding error.'
  };
}

async function getBody(response) {
  const reader = response.body?.getReader();
  if (!reader) return '';
  const pieces = [];
  let total = 0;
  try {
    for (;;) {
      const {value, done} = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > MAX_JSON_BYTES) throw new RangeError('HTTP response exceeds read-only byte limit');
      pieces.push(value);
    }
  } finally { reader.releaseLock(); }
  return Buffer.concat(pieces, total).toString('utf8');
}

async function readEndpoint(fetchImpl, url, {json = false} = {}) {
  const response = await fetchImpl(url, {
    method: 'GET', redirect: 'error', headers: {accept: 'application/json'},
    signal: AbortSignal.timeout(15_000)
  });
  const header = response.headers;
  const body = json && response.ok ? JSON.parse(await getBody(response)) : null;
  return {status: response.status, header, body};
}

function listItems(page) {
  if (Array.isArray(page?.items)) return page.items;
  if (Array.isArray(page?.resources)) return page.resources;
  throw new TypeError('Discovery body has no items/resources array');
}

function networkSummary(item) {
  return [...new Set((Array.isArray(item?.accepts) ? item.accepts : [])
    .map(x => x?.network).filter(x => typeof x === 'string'))];
}

export async function inspectCatalog({catalogUrl, targetResource, payTo, network, allowLoopback = false,
  pageLimit = 100, maxPages = 500, fetchImpl = fetch}) {
  const endpoint = requireEndpoint(catalogUrl, {allowLoopback});
  const target = resourceKey(targetResource);
  if (!target) throw new TypeError('Invalid target resource URL');
  if (!Number.isSafeInteger(pageLimit) || pageLimit < 1 || pageLimit > 200 ||
      !Number.isSafeInteger(maxPages) || maxPages < 1 || maxPages > 2000) {
    throw new TypeError('Invalid pagination options');
  }
  const matches = [], samePayToOtherResource = [];
  // Read the original operation contract across every matching record, not just displayed samples.
  const httpMethods = new Set();
  let mcpToolCount = 0, unresolvedMethodCount = 0;
  // Keep a bounded sample for display, but classify using ALL matching records.
  let matchingResourceCount = 0;
  const matchEvidence = {network: false, payTo: false, paired: false};
  const seenKeys = new Set(), seenPageSignatures = new Set(), seenCursors = new Set();
  let offset = 0, cursor = null, useCursor = false, knownTotal = null;
  let complete = false, pages = 0, rawRows = 0, reason = null;
  for (let i = 0; i < maxPages; i++) {
    const pageUrl = new URL(endpoint);
    pageUrl.searchParams.set('limit', String(pageLimit));
    if (useCursor) pageUrl.searchParams.set('cursor', cursor);
    else pageUrl.searchParams.set('offset', String(offset));
    let body;
    try {
      const result = await readEndpoint(fetchImpl, pageUrl, {json: true});
      if (result.status !== 200) throw new Error(`Discovery HTTP ${result.status}`);
      body = result.body;
    } catch (error) { reason = `Page ${i + 1}: ${String(error.message)}`; break; }
    let items;
    try { items = listItems(body); }
    catch (error) { reason = `Page ${i + 1}: ${String(error.message)}`; break; }
    pages++;
    rawRows += items.length;
    const pageKeys = [];
    for (const item of items) {
      const resource = resourceKey(item?.resource);
      const toolName = item?.extensions?.bazaar?.info?.input?.toolName ?? '';
      const uniqueKey = `${resource ?? '?'}\0${toolName}`;
      pageKeys.push(uniqueKey);
      seenKeys.add(uniqueKey);
      const accepts = Array.isArray(item?.accepts) ? item.accepts : [];
      const related = typeof payTo === 'string' && accepts.some(x =>
        typeof x?.payTo === 'string' && x.payTo.toLowerCase() === payTo.toLowerCase());
      const hasNetwork = network ? accepts.some(x => x?.network === network) : null;
      // It is not enough for network and recipient to occur on DIFFERENT
      // alternatives; the seller must actually accept their paired route.
      const hasPair = network && payTo ? accepts.some(x =>
        x?.network === network && typeof x?.payTo === 'string' &&
        x.payTo.toLowerCase() === payTo.toLowerCase()) : null;
      if (resource === target) {
        matchingResourceCount++;
        const input = item?.extensions?.bazaar?.info?.input;
        const kind = item?.type ?? input?.type;
        const method = typeof input?.method === 'string' ? input.method.toUpperCase() : null;
        if (kind === 'mcp' && input?.type === 'mcp') mcpToolCount++;
        else if (kind === 'http' && HTTP_METHODS.has(method)) httpMethods.add(method);
        else unresolvedMethodCount++;
        matchEvidence.network ||= Boolean(hasNetwork);
        matchEvidence.payTo ||= Boolean(related);
        matchEvidence.paired ||= Boolean(hasPair);
        if (matches.length < 50) matches.push({resource, type: item?.type ?? null,
          toolName: String(toolName), x402Version: item?.x402Version ?? null,
          networks: networkSummary(item), declaredMethod: kind === 'http' && HTTP_METHODS.has(method) ? method : null,
          declaredType: kind ?? null, desiredNetworkFound: hasNetwork,
          desiredPayToFound: payTo ? related : null, desiredPaymentRouteFound: hasPair});
      } else if (related && samePayToOtherResource.length < 15) {
        samePayToOtherResource.push({resource, networks: networkSummary(item)});
      }
    }
    const signature = pageKeys.join('\n');
    if (items.length && seenPageSignatures.has(signature)) {
      reason = `Repeated page contents at page ${pages}; provider may ignore pagination`; break;
    }
    seenPageSignatures.add(signature);
    const pagination = body?.pagination && typeof body.pagination === 'object' ? body.pagination : {};
    if (Number.isSafeInteger(pagination.total) && pagination.total >= 0) knownTotal = pagination.total;
    const nextCursor = pagination.nextCursor ?? pagination.next_cursor ?? pagination.cursor;
    // A filtered cursor page may legitimately be empty while another page has
    // rows. Follow its actual next cursor BEFORE claiming the catalog exhausted.
    // A repeated cursor (including A -> B -> A) cannot establish exhaustion.
    if (typeof nextCursor === 'string' && nextCursor.length > 0) {
      if (seenCursors.has(nextCursor) || (useCursor && nextCursor === cursor)) {
        reason = `Repeated cursor at page ${pages}; provider pagination made no progress`;
        break;
      }
      seenCursors.add(nextCursor);
      useCursor = true;
      cursor = nextCursor;
      continue;
    }
    if (knownTotal !== null && seenKeys.size > knownTotal) {
      reason = 'Provider declared total contradicts observed unique rows';
      break;
    }
    if (useCursor) {
      if (knownTotal !== null && seenKeys.size < knownTotal) reason = 'Cursor ended before declared total';
      else complete = true;
      break;
    }
    if (knownTotal !== null && seenKeys.size >= knownTotal) { complete = true; break; }
    if (!items.length) {
      if (knownTotal !== null && seenKeys.size < knownTotal) reason = 'Empty page before declared total';
      else complete = true;
      break;
    }
    // Offset-only providers without a total get an extra empty-page probe.
    offset += items.length;
  }
  if (!complete && !reason) reason = `Reached maxPages=${maxPages} before proving catalog exhaustiveness`;
  return {endpoint: endpoint.toString(), pages, rawRows, uniqueKeys: seenKeys.size,
    declaredTotal: knownTotal, complete, incompleteReason: reason,
    matchingResourceCount,
    operationEvidence: {httpMethods: [...httpMethods].sort(), mcpToolCount, unresolvedMethodCount},
    matchingEvidence: {
      desiredNetworkFound: network ? matchEvidence.network : null,
      desiredPayToFound: payTo ? matchEvidence.payTo : null,
      desiredPaymentRouteFound: network && payTo ? matchEvidence.paired : null
    },
    matches, matchingPayToOtherResources: samePayToOtherResource};
}

export async function diagnose({resourceUrl, catalogUrl, payTo, network, extensionResponses,
  allowLoopback = false, pageLimit = 100, maxPages = 500, fetchImpl = fetch}) {
  const resource = requireEndpoint(resourceUrl, {allowLoopback});
  const catalog = requireEndpoint(catalogUrl, {allowLoopback});
  async function probeUnpaidGet() {
    try {
      const result = await readEndpoint(fetchImpl, resource);
      return inspectChallenge(result.status, result.header.get('payment-required'));
    } catch (error) { return {state: 'FETCH_ERROR', error: String(error.message)}; }
  }
  const inspect = requestedPayTo => inspectCatalog({catalogUrl: catalog.toString(), targetResource: resource.toString(),
    payTo: requestedPayTo, network, allowLoopback, pageLimit, maxPages, fetchImpl});
  let challenge, summary;
  if (payTo) {
    // An explicit seller recipient permits one catalog pass before an origin probe.
    // Skip GET only when COMPLETE source records all declare non-GET or MCP operations.
    summary = await inspect(payTo);
    const methods = summary.operationEvidence;
    const skipGet = summary.complete && summary.matchingResourceCount > 0 &&
      methods.unresolvedMethodCount === 0 && !methods.httpMethods.includes('GET') &&
      (methods.httpMethods.length > 0 || methods.mcpToolCount > 0);
    challenge = skipGet ? {state: 'CATALOG_NON_GET_ONLY', observedVia: 'COMPLETE_CATALOG',
      declaredHttpMethods: methods.httpMethods, mcpToolCount: methods.mcpToolCount} : await probeUnpaidGet();
  } else {
    // Retain original single-offer payTo derivation when no recipient was given.
    // In that case the genuine origin response must precede the indexed catalog comparison.
    challenge = await probeUnpaidGet();
    const discoveredPayTo = challenge.acceptsCount === 1 ? challenge.accepts?.[0]?.payTo : null;
    summary = await inspect(discoveredPayTo);
  }
  const derivedPayTo = payTo || (challenge.acceptsCount === 1 ? challenge.accepts?.[0]?.payTo : null);
  const extension = bazaarExtensionOutcome(extensionResponses);
  let verdict = 'INCONCLUSIVE_CATALOG';
  if (summary.matchingResourceCount) {
    if (network && !summary.matchingEvidence.desiredNetworkFound)
      verdict = 'LISTED_WRONG_NETWORK';
    else if (derivedPayTo && !summary.matchingEvidence.desiredPayToFound)
      verdict = 'LISTED_WRONG_PAYTO';
    else if (network && derivedPayTo && !summary.matchingEvidence.desiredPaymentRouteFound)
      verdict = 'LISTED_PAYMENT_ROUTE_MISMATCH';
    else verdict = 'LISTED';
  } else if (summary.complete) verdict = 'NOT_LISTED_IN_EXHAUSTED_CATALOG';
  return {
    schema: 'stellar-forge.seller-visibility.v1', mode: 'READ_ONLY_UNAUTHENTICATED',
    seller: resource.toString(), network: network ?? null, desiredPayTo: derivedPayTo ?? null,
    challenge, sellerDiscovery: sellerDiscoveryReadiness(challenge), extensionResponse: extension, catalog: summary, verdict,
    interpretation: verdict === 'NOT_LISTED_IN_EXHAUSTED_CATALOG'
      ? (challenge.state === 'UNPAID_GET_HTTP_200'
        ? 'Not listed in this exhausted catalog, and the seller gave an unpaid HTTP 200 rather than a 402 declaration. Free-tier or cache shortcuts can prevent crawler discovery; verify the challenge path before attributing absence to the facilitator.'
        : 'Missing from this facilitator catalog at read time; successful payment alone does not prove catalog indexing.')
      : verdict === 'INCONCLUSIVE_CATALOG'
        ? 'Catalog coverage incomplete; do not interpret this as absence.'
        : verdict === 'LISTED_PAYMENT_ROUTE_MISMATCH'
          ? 'URL indexed, but no single accepted option combines the requested network and payTo.'
          : verdict === 'LISTED_WRONG_PAYTO'
            ? 'URL indexed, but its listed payment recipients do not match the seller recipient.'
            : 'Listing observed; check matching network, payment terms and seller origin separately.',
    excludes: ['No settlement or wallet verification', 'No facilitator indexing trigger', 'No payment made']
  };
}

function parseArgs(args) {
  const options = {};
  const values = new Set(['--resource','--catalog','--pay-to','--network','--extension-responses',
    '--extension-responses-file','--limit','--max-pages']);
  for (let i = 0; i < args.length; i++) {
    const flag = args[i];
    if (flag === '--allow-loopback') { options.allowLoopback = true; continue; }
    if (!values.has(flag) || !args[i+1] || args[i+1].startsWith('--')) throw new TypeError(`Invalid option: ${flag}`);
    const value = args[++i];
    const mapping = {'--resource':'resourceUrl','--catalog':'catalogUrl','--pay-to':'payTo',
      '--network':'network','--extension-responses':'extensionResponses',
      '--extension-responses-file':'extensionResponsesFile','--limit':'pageLimit','--max-pages':'maxPages'};
    options[mapping[flag]] = ['--limit','--max-pages'].includes(flag) ? Number(value) : value;
  }
  if (!options.resourceUrl || !options.catalogUrl) throw new TypeError('--resource and --catalog required');
  if (options.extensionResponses && options.extensionResponsesFile) throw new TypeError('Supply extension response in only one place');
  return options;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  (async () => {
    const options = parseArgs(process.argv.slice(2));
    if (options.extensionResponsesFile) {
      options.extensionResponses = (await readFile(options.extensionResponsesFile, 'utf8')).trim();
      delete options.extensionResponsesFile;
    }
    const result = await diagnose(options);
    process.stdout.write(JSON.stringify(result, null, 2) + '\n');
  })().catch(error => {
    process.stderr.write('SF52 diagnostic error: ' + String(error.message) + '\n');
    process.exitCode = 1;
  });
}

// MIT. Read-only browser checkout readiness for actual x402 seller HTTP endpoints.
// Checks unauthenticated GET + CORS OPTIONS, never paid operations, signatures or POST.
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { resolve } from 'node:path';
import { supportsSellerMethod } from '../sf30-seller-sdk/http-methods.mjs';

const FIELDS = Object.freeze([
  'access-control-allow-origin', 'access-control-allow-credentials',
  'access-control-allow-headers', 'access-control-allow-methods',
  'access-control-expose-headers', 'vary',
]);
const USAGE = `Browser x402 preflight audit (Node 22+, read-only)\n  node audit.mjs --resource https://seller.example/paid --origin https://buyer.example [--method GET|HEAD|POST|PUT|PATCH|DELETE] [--credentialed] [--out private.json]\n  Use --allow-loopback ONLY for explicit http://127.0.0.1 seller + buyer fixtures.\n  Performs actual unpaid GET and OPTIONS, not the method supplied as --method.`;

function tokens(s) {
  return new Set(String(s ?? '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean));
}

function urlOf(s, {loopback = false, originOnly = false} = {}) {
  const u = new URL(s);
  if (u.username || u.password || u.hash || !['https:', 'http:'].includes(u.protocol))
    throw new TypeError('Source URL cannot have credentials, fragments or invalid protocol');
  if (u.protocol === 'http:' && !(loopback && u.hostname === '127.0.0.1'))
    throw new TypeError('Plain HTTP requires explicit literal 127.0.0.1 --allow-loopback');
  if (u.protocol === 'https:' && (u.hostname === '127.0.0.1' || u.hostname === 'localhost'))
    throw new TypeError('Private loopback target requires explicit http://127.0.0.1 --allow-loopback');
  if (originOnly && (u.pathname !== '/' || u.search))
    throw new TypeError('Buyer origin must have no path, query, username or fragment');
  return u;
}

function optionArgs(args) {
  const fields = new Set(['--resource', '--origin', '--method', '--out']);
  const switches = new Set(['--credentialed', '--allow-loopback', '--help']);
  const vals = new Map(), flags = new Set();
  for (let i=0; i<args.length; i++) {
    const name = args[i];
    if (switches.has(name)) {
      if (flags.has(name)) throw new TypeError('Duplicate ' + name);
      flags.add(name);
    } else if (fields.has(name)) {
      if (vals.has(name) || !args[i+1] || args[i+1].startsWith('--'))
        throw new TypeError('Missing/duplicate ' + name);
      vals.set(name,args[++i]);
    } else throw new TypeError('Unknown option: ' + name);
  }
  if (flags.has('--help')) {
    if (fields.size === 0) return {help:true};
    if (vals.size || flags.size!==1) throw new TypeError('--help must be alone');
    return {help:true};
  }
  if (!vals.has('--resource') || !vals.has('--origin')) throw new TypeError('Missing seller and browser origin');
  const loopback=flags.has('--allow-loopback');
  const resource=urlOf(vals.get('--resource'),{loopback});
  const origin=urlOf(vals.get('--origin'),{loopback,originOnly:true}).origin;
  const method=vals.get('--method')??'GET';
  if (!supportsSellerMethod(method)) throw new TypeError('Unknown preflight method');
  if (resource.origin===origin) throw new TypeError('Choose a distinct buyer origin for actual cross-origin acceptance');
  return {resource:resource.href,origin,method,credentialed:flags.has('--credentialed'),out:vals.get('--out')};
}

function readCors(headers) {
  const out={};
  for (const k of FIELDS) out[k]=headers.get(k)??null;
  return out;
}

function allowsOrigin(h, origin, credentialed) {
  const actual = h['access-control-allow-origin'];
  if (actual !== origin && !(actual==='*' && !credentialed)) return false;
  if (credentialed && h['access-control-allow-credentials']!=='true') return false;
  return true;
}
function allowsToken(value, desired, credentialed) {
  const set=tokens(value);
  return set.has(desired.toLowerCase()) || (set.has('*') && !credentialed);
}

/** Evaluation of real HTTP header observations using browser CORS rules. */
export function assess({resource,origin,method='GET',credentialed=false,getStatus,getHeaders,
  optionsStatus,optionsHeaders,hasPaymentRequired=false}) {
  if (!getHeaders || !optionsHeaders || typeof origin!=='string')
    throw new TypeError('Original GET and OPTIONS observations required');
  const findings=[];
  const finding=(severity,code,repair)=>findings.push({severity,code,repair});
  const getOrigin=allowsOrigin(getHeaders,origin,credentialed);
  const readable=getOrigin && allowsToken(getHeaders['access-control-expose-headers'],'payment-required',credentialed);
  const preflightOrigin=allowsOrigin(optionsHeaders,origin,credentialed);
  const preflightStatus=Number.isInteger(optionsStatus) && optionsStatus>=200 && optionsStatus<300;
  const methodAllowed=allowsToken(optionsHeaders['access-control-allow-methods'],method,credentialed);
  const paymentAllowed=allowsToken(optionsHeaders['access-control-allow-headers'],'payment-signature',credentialed);
  if (getStatus!==402) finding('HIGH','UNPAID_GET_NOT_402','Inspect the actual advertised paid method and seller discovery behavior. A plain GET is not proof of a valid payment challenge.');
  else if (!hasPaymentRequired) finding('HIGH','NO_PAYMENT_REQUIRED','Emit a valid x402 v2 PAYMENT-REQUIRED challenge header on unpaid requests.');
  if (!getOrigin) finding('HIGH','GET_CORS_ORIGIN','Ensure the actual HTTP 402 carries exactly one permitted Access-Control-Allow-Origin value; credentialed requests require a specific origin and Allow-Credentials: true.');
  else if (!readable) finding('HIGH','CHALLENGE_NOT_BROWSER_READABLE','Union PAYMENT-REQUIRED with the existing Access-Control-Expose-Headers; preserve any other exposed receipt/application headers.');
  if (!preflightStatus) finding('HIGH','PREFLIGHT_NOT_2XX','Answer browser OPTIONS successfully before the payment middleware; never require payment to preflight.');
  if (!preflightOrigin) finding('HIGH','PREFLIGHT_CORS_ORIGIN','Apply permitted Access-Control-Allow-Origin to OPTIONS as well as the 402; avoid duplicate comma-joined values.');
  if (!methodAllowed) finding('HIGH','PREFLIGHT_METHOD','Include the paid retry method in Access-Control-Allow-Methods, or use a noncredentialed wildcard.');
  if (!paymentAllowed) finding('HIGH','PREFLIGHT_PAYMENT_HEADER','Include PAYMENT-SIGNATURE in Access-Control-Allow-Headers; credentialed browser requests cannot rely on a wildcard.');
  const ready=(getStatus===402 && hasPaymentRequired && readable && preflightStatus && preflightOrigin && methodAllowed && paymentAllowed);
  return {
    schema:'stellar-forge.browser-x402-readiness.v1',resource,origin,method,credentialed,
    status:ready?'READABLE_402_AND_PREFLIGHT_READY':'BROWSER_CHECKOUT_REMEDIATION',
    evidence:{getStatus,optionsStatus,hasPaymentRequired,getCors:getHeaders,optionsCors:optionsHeaders,
      GET_402_browser_visible:getOrigin && readable, preflightReady:preflightStatus && preflightOrigin && methodAllowed && paymentAllowed},
    findings,
    limitations:'GET/OPTIONS browser-header preflight only; no native paid retry, payment settlement, receipt, account auth or delivery test.',
  };
}

async function headerRequest(url, method, headers) {
  const response=await fetch(url,{method,headers,redirect:'error',signal:AbortSignal.timeout(12000)});
  try { return {status:response.status,cors:readCors(response.headers),hasPaymentRequired:response.headers.has('payment-required')}; }
  finally { await response.body?.cancel(); }
}

export async function probe(config) {
  const unpaid=await headerRequest(config.resource,'GET',{'Origin':config.origin,'Accept':'application/json'});
  const preflight=await headerRequest(config.resource,'OPTIONS',{
    'Origin':config.origin,'Access-Control-Request-Method':config.method,
    'Access-Control-Request-Headers':'payment-signature',
  });
  const evaluation=assess({...config,getStatus:unpaid.status,getHeaders:unpaid.cors,
    optionsStatus:preflight.status,optionsHeaders:preflight.cors,hasPaymentRequired:unpaid.hasPaymentRequired});
  return {...evaluation,observedAt:new Date().toISOString(),readOnly:true,paidRequests:0};
}

export async function run(args=process.argv.slice(2)) {
  const config=optionArgs(args);
  if (config.help) { console.log(USAGE); return; }
  const report=await probe(config);
  const output=JSON.stringify(report,null,2)+'\n';
  if (config.out) await writeFile(config.out,output,{flag:'wx',mode:0o600});
  console.log(output);
  if (report.status==='BROWSER_CHECKOUT_REMEDIATION') process.exitCode=2;
}

if (process.argv[1] && fileURLToPath(import.meta.url)===resolve(process.argv[1])) {
  run().catch(e=>{ console.error('SF68: '+e.message); process.exitCode=1; });
}

// MIT. Single merchant-scoped integration of the published SF52 and SF68 original HTTP diagnostics.
// No signing, credentialed requests, paid HTTP retry, or settlement operations.
import {writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import {resolve} from 'node:path';
import {diagnose, requireEndpoint} from '../sf52-merchant-visibility/diagnose.mjs';
import {probe} from '../sf68-browser-payment-readiness/audit.mjs';
import {supportsSellerMethod} from '../sf30-seller-sdk/http-methods.mjs';

const VALUE_FLAGS = new Set(['--resource','--catalog','--origin','--network','--pay-to','--method','--out']);
const SWITCH_FLAGS = new Set(['--credentialed','--allow-loopback','--help']);
const HELP = [
  'SF70 merchant one-pass intake (read-only, Node 22+)',
  'node run.mjs --resource https://seller.example/paid --catalog https://facilitator.example/discovery/resources',
  '  --origin https://buyer.example --network stellar:testnet --pay-to G... [--method GET|HEAD|POST|PUT|PATCH|DELETE]',
  '  [--credentialed] [--out private.json]',
  'For local original HTTP fixtures only: --allow-loopback with literal http://127.0.0.1 URLs.',
  'Performs original catalog GET pages; GET/OPTIONS browser checks only where GET is a relevant advertised operation. Never signs or pays.'
].join('\n');

export function parseArgs(argv) {
  const values = new Map(), switches = new Set();
  for (let i=0;i<argv.length;i++) {
    const key = argv[i];
    if (SWITCH_FLAGS.has(key)) {
      if (switches.has(key)) throw new TypeError('Duplicate option: '+key);
      switches.add(key);
    } else if (VALUE_FLAGS.has(key)) {
      if (values.has(key) || !argv[i+1] || argv[i+1].startsWith('--'))
        throw new TypeError('Missing or repeated option: '+key);
      values.set(key,argv[++i]);
    } else throw new TypeError('Unknown option: '+key);
  }
  if (switches.has('--help')) {
    if (switches.size!==1 || values.size) throw new TypeError('--help must be alone');
    return {help:true};
  }
  for (const field of ['--resource','--catalog','--origin','--network','--pay-to']) {
    if (!values.has(field)) throw new TypeError('Required: '+field);
  }
  const allowLoopback=switches.has('--allow-loopback');
  const resource=requireEndpoint(values.get('--resource'),{allowLoopback});
  const catalog=requireEndpoint(values.get('--catalog'),{allowLoopback});
  const browser=requireEndpoint(values.get('--origin'),{allowLoopback});
  if (browser.pathname!=='/' || browser.search || browser.hash)
    throw new TypeError('Buyer origin must have no path or query');
  if (resource.origin===browser.origin) throw new TypeError('Buyer origin must differ from seller');
  const network=values.get('--network');
  if (!/^stellar:[a-z0-9-]{2,32}$/.test(network)) throw new TypeError('Expected exact stellar:* network');
  const payTo=values.get('--pay-to');
  if (!payTo.trim() || payTo!==payTo.trim() || payTo.length>256)
    throw new TypeError('Invalid seller payment recipient');
  const method=values.get('--method')||'GET';
  if (!supportsSellerMethod(method))
    throw new TypeError('Unsupported intended buyer retry method');
  const out=values.get('--out');
  if (out && out.length>2048) throw new TypeError('Report path too long');
  return {resourceUrl:resource.toString(),catalogUrl:catalog.toString(),origin:browser.origin,
    network,payTo,method,credentialed:switches.has('--credentialed'),allowLoopback,out};
}

export function combine({seller,browser,error,config,observedAt}) {
  const findings=[];
  const add=(severity,code,action)=>findings.push({severity,code,action});
  const nonGetOnly=seller.sellerDiscovery.state==='CATALOG_NON_GET_ONLY';
  if (nonGetOnly)
    add('UNKNOWN','NON_GET_OR_MCP_ONLY',
      'Source catalog lists non-GET HTTP or MCP operations. An unpaid GET is not a valid checkout test of this route; original advertised operation needs its own authorized verification.');
  else if (seller.sellerDiscovery.state!=='UNPAID_402_BAZAAR_VISIBLE')
    add('HIGH','SELLER_UNPAID_DISCOVERY',
      'Verify the advertised unpaid GET operation returns a valid 402 PAYMENT-REQUIRED with Bazaar extension.');
  if (!seller.catalog.complete)
    add('UNKNOWN','CATALOG_NOT_EXHAUSTIVE',
      'Finish actual facilitator pagination or resolve the reported provider error before claiming listing absence.');
  if (seller.verdict==='INCONCLUSIVE_CATALOG') {
    if (seller.catalog.complete) add('UNKNOWN','CATALOG_INCONCLUSIVE','Review original SF52 catalog and provider response.');
  } else if (seller.verdict!=='LISTED')
    add('HIGH','CATALOG_ROUTE_MISMATCH',
      'Confirm the identical resource operation has a single accepted Stellar network and payTo in the facilitator listing.');
  else if (seller.catalog.matchingEvidence.desiredPaymentRouteFound!==true)
    add('HIGH','CATALOG_PAIRED_TERMS',
      'Require network and recipient on the same accepted payment alternative.');
  if (!browser && nonGetOnly) add('UNKNOWN','BROWSER_METHOD_UNASSESSED',
    'SF68 GET/OPTIONS audit is not a checkout test for a confirmed non-GET/MCP-only catalog offer. Assess the actual authorized operation in a separate browser-aware integration.');
  else if (!browser) add('UNKNOWN','BROWSER_HTTP_UNAVAILABLE',
    'Repeat the original unpaid browser-origin GET and OPTIONS; '+String(error||'request failed').slice(0,200));
  else if (browser.status!=='READABLE_402_AND_PREFLIGHT_READY')
    for (const f of browser.findings)
      add(f.severity==='HIGH'?'HIGH':'UNKNOWN','BROWSER_'+f.code,f.repair);
  const state=findings.some(f=>f.severity==='HIGH')?'REMEDIATION_REQUIRED':
    findings.length?'INCONCLUSIVE':'UNPAID_DISCOVERY_AND_BROWSER_READY';
  return {
    schema:'stellar-forge.merchant-intake.v1',state,observedAt,
    scope:{resource:config.resourceUrl,catalog:config.catalogUrl,buyerOrigin:config.origin,
      network:config.network,payTo:config.payTo,intendedRetryMethod:config.method,
      browserCredentialed:config.credentialed===true},
    findings,
    originals:{sellerCatalog:seller,browserReadiness:browser??null,browserError:error??null},
    safeguards:{walletCalls:0,paidRequests:0,settlementConfirmed:false,
      buyerAuthorizationConfirmed:false,sellerPermissionConfirmed:false,
      description:'Catalog GET pages plus GET/OPTIONS only when the original offer supports GET; no paid request, customer acceptance or settlement.'}
  };
}

export async function capture(config) {
  const observedAt=new Date().toISOString();
  // Preserve original implementations, including redirect/timeout and catalog pagination boundaries.
  const seller=await diagnose({resourceUrl:config.resourceUrl,catalogUrl:config.catalogUrl,
    network:config.network,payTo:config.payTo,allowLoopback:config.allowLoopback});
  let browser=null,error=null;
  // The genuine method-aware SF52 catalog can establish a POST/MCP-only offer.
  // Do not reintroduce a misleading unpaid GET or CORS diagnosis for that offer.
  if (seller.sellerDiscovery.state!=='CATALOG_NON_GET_ONLY') {
    try {
      browser=await probe({resource:config.resourceUrl,origin:config.origin,
        method:config.method,credentialed:config.credentialed});
    } catch (e) { error=String(e?.message||e).slice(0,200); }
  }
  return combine({seller,browser,error,config,observedAt});
}

export async function main(argv=process.argv.slice(2)) {
  const config=parseArgs(argv);
  if (config.help) {process.stdout.write(HELP+'\n');return;}
  const report=await capture(config);
  const json=JSON.stringify(report,null,2)+'\n';
  if (config.out) await writeFile(config.out,json,{flag:'wx',mode:0o600});
  process.stdout.write(json);
  if (report.state==='REMEDIATION_REQUIRED') process.exitCode=2;
  else if (report.state==='INCONCLUSIVE') process.exitCode=3;
}
if (process.argv[1] && resolve(process.argv[1])===fileURLToPath(import.meta.url)) {
  main().catch(e=>{process.stderr.write('SF70 merchant intake: '+String(e.message)+'\n');process.exitCode=1;});
}

// MIT. SF72: unpaid browser preflight for catalog-proven, HTTP POST-only x402 offers.
// Consumes an ORIGINAL SF70 merchant-intake JSON output; never issues GET, POST, signatures or payments.
import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const MAX_INPUT = 2_000_000;
const HEADER_FIELDS = ['access-control-allow-origin', 'access-control-allow-credentials',
  'access-control-allow-methods', 'access-control-allow-headers', 'vary'];
const USAGE = [
  'SF72 POST-only x402 browser preflight (Node 22+, no dependencies)',
  'node preflight.mjs --intake /private/original-sf70.json --out /private/post-preflight.json [--credentialed]',
  'Only original SF70 reports proving one complete POST-only HTTP catalog route are eligible.',
  'OPTIONS-only; never GET, POST, payment, signature or seller-origin challenge requests.',
  '--allow-loopback is permitted only for local http://127.0.0.1 acceptance servers.',
].join('\n');

function parseArgs(argv) {
  const values = new Map(), flags = new Set();
  for (let i=0;i<argv.length;i++) {
    const k=argv[i];
    if (['--credentialed','--allow-loopback','--help'].includes(k)) {
      if (flags.has(k)) throw new TypeError('Repeated '+k);
      flags.add(k);
    } else if (['--intake','--out'].includes(k)) {
      if (values.has(k)||!argv[i+1]||argv[i+1].startsWith('--')) throw new TypeError('Missing/repeated '+k);
      values.set(k,argv[++i]);
    } else throw new TypeError('Unknown '+k);
  }
  if (flags.has('--help')) {
    if (flags.size!==1||values.size) throw new TypeError('--help must be used alone');
    return {help:true};
  }
  if (!values.has('--intake')) throw new TypeError('Required --intake path');
  return {intake:values.get('--intake'),out:values.get('--out'),
    credentialed:flags.has('--credentialed'),allowLoopback:flags.has('--allow-loopback')};
}

function safeResource(raw, allowLoopback) {
  if (typeof raw!=='string'||raw.length>2048) throw new TypeError('Invalid SF70 resource URL');
  const u = new URL(raw);
  if (u.username||u.password||u.hash) throw new TypeError('Credentials/fragments not allowed');
  const local = u.hostname === '127.0.0.1';
  if (!(u.protocol==='https:' && !local && u.hostname!=='localhost') &&
      !(u.protocol==='http:' && local && allowLoopback)) throw new TypeError('HTTPS required; loopback needs explicit flag');
  // Do not send probes to a literal private IPv4 target, link-local host or metadata endpoint.
  const h=u.hostname.toLowerCase();
  if (/^(?:10\.|127\.|169\.254\.|192\.168\.|172\.(?:1[6-9]|2\d|3[01])\.)/.test(h) && !local)
    throw new TypeError('Private IP seller target not permitted');
  if (/^(?:.*\.localhost|.*\.local|.*\.internal)$/.test(h) || h==='[::1]')
    throw new TypeError('Local/private hostname not permitted');
  return u;
}

function corsTokens(raw) {
  return new Set(String(raw||'').split(',').map(s=>s.trim().toLowerCase()).filter(Boolean));
}
function tokenAllowed(raw, target, credentialed) {
  const t=corsTokens(raw);
  return t.has(target.toLowerCase()) || (!credentialed && t.has('*'));
}
function allowOrigin(raw, original, credentialed, credentials) {
  return (raw===original || (raw==='*'&&!credentialed)) &&
    (!credentialed || credentials==='true');
}

/** Only an exhaustive, self-consistent original SF70 catalog snapshot authorizes an OPTIONS probe. */
export function eligibleIntake(intake) {
  if (!intake || intake.schema!=='stellar-forge.merchant-intake.v1' ||
      intake.originals?.sellerCatalog?.schema!=='stellar-forge.seller-visibility.v1')
    return {ok:false,reason:'ORIGINAL_SF70_REQUIRED'};
  const catalog=intake.originals.sellerCatalog.catalog;
  const evidence=catalog?.operationEvidence;
  if (intake.originals.sellerCatalog.sellerDiscovery?.state!=='CATALOG_NON_GET_ONLY' ||
      !catalog?.complete || !Number.isSafeInteger(catalog.matchingResourceCount) ||
      catalog.matchingResourceCount<1 || catalog.matchingEvidence?.desiredPaymentRouteFound!==true ||
      !evidence || evidence.unresolvedMethodCount!==0 || evidence.mcpToolCount!==0 ||
      !Array.isArray(evidence.httpMethods) || evidence.httpMethods.length!==1 ||
      evidence.httpMethods[0]!=='POST' || intake.scope?.intendedRetryMethod!=='POST' ||
      intake.originals.browserReadiness!==null)
    return {ok:false,reason:'NOT_PROVEN_POST_ONLY_HTTP_PAYMENT_ROUTE'};
  if (intake.scope?.resource!==intake.originals.sellerCatalog.seller ||
      intake.scope?.catalog!==catalog.endpoint ||
      intake.scope?.network!==intake.originals.sellerCatalog.network ||
      intake.scope?.payTo!==intake.originals.sellerCatalog.desiredPayTo ||
      !intake.scope?.buyerOrigin)
    return {ok:false,reason:'SF70_SOURCE_SCOPE_MISMATCH'};
  return {ok:true,reason:'EXHAUSTIVE_POST_ONLY_HTTP_CATALOG'};
}

/** Pure browser CORS evaluation of exact received OPTIONS headers, no HTTP calls. */
export function assessPreflight({origin,credentialed=false,status,headers}) {
  const h=headers;
  const findings=[];
  const add=(code,action)=>findings.push({severity:'HIGH',code,action});
  if (!Number.isInteger(status)||status<200||status>=300)
    add('OPTIONS_NOT_2XX','Handle browser OPTIONS without requesting payment.');
  if (!allowOrigin(h['access-control-allow-origin'],origin,credentialed,h['access-control-allow-credentials']))
    add('ORIGIN_NOT_ALLOWED','Permit only the specified buyer Origin; credentialed browser calls need exact origin and Allow-Credentials:true.');
  if (!tokenAllowed(h['access-control-allow-methods'],'POST',credentialed))
    add('POST_NOT_ALLOWED','Advertise the seller POST operation in Access-Control-Allow-Methods.');
  for (const name of ['payment-signature','content-type']) {
    if (!tokenAllowed(h['access-control-allow-headers'],name,credentialed))
      add('HEADER_NOT_ALLOWED_'+name.toUpperCase().replace('-','_'),
        'Allow '+name+' in Access-Control-Allow-Headers for browser x402 JSON POST retries.');
  }
  return {status:findings.length?'PREFLIGHT_REMEDIATION':'POST_PREFLIGHT_READY_CHALLENGE_UNKNOWN',
    observed:{optionsStatus:status,optionsCors:h},findings,
    limitations:'Only observed OPTIONS CORS headers. No POST, payment challenge, x402 signature, settlement, buyer authorization, server payload, browser execution or service delivery was tested.'};
}

function selectHeaders(headers) {
  return Object.fromEntries(HEADER_FIELDS.map(k=>[k,headers.get(k)??null]));
}

export async function evaluate(intake, {credentialed=false,allowLoopback=false,fetchImpl=fetch,observedAt=new Date().toISOString()}={}) {
  const eligibility=eligibleIntake(intake);
  const summary={schema:'stellar-forge.post-only-browser-preflight.v1',
    source:{originalSchema:intake?.schema??null,originalObservedAt:intake?.observedAt??null,
      resource:intake?.scope?.resource??null,catalog:intake?.scope?.catalog??null,
      network:intake?.scope?.network??null,origin:intake?.scope?.buyerOrigin??null},
    observedAt,method:'OPTIONS_ONLY',credentialed,
    operations:{OPTIONS:0,GET:0,POST:0,payments:0,signatures:0},eligibility};
  if (!eligibility.ok) return {...summary,status:'INCONCLUSIVE',findings:[],
    limitations:'Original SF70 must prove a complete and consistent single HTTP POST-only payment route; no network request made.'};
  const seller=safeResource(intake.scope.resource,allowLoopback);
  const origin=new URL(intake.scope.buyerOrigin);
  if (!['https:','http:'].includes(origin.protocol)||origin.origin!==intake.scope.buyerOrigin ||
      origin.username || origin.password || origin.pathname!=='/' || origin.search || origin.hash ||
      (origin.protocol==='http:' && !(allowLoopback && origin.hostname==='127.0.0.1')) ||
      seller.origin===origin.origin) throw new TypeError('Invalid distinct buyer origin');
  const response=await fetchImpl(seller,{method:'OPTIONS',redirect:'error',
    headers:{Origin:origin.origin,'Access-Control-Request-Method':'POST',
      'Access-Control-Request-Headers':'payment-signature,content-type'},
    signal:AbortSignal.timeout(12000)});
  try {
    const assessment=assessPreflight({origin:origin.origin,credentialed,status:response.status,
      headers:selectHeaders(response.headers)});
    return {...summary,operations:{...summary.operations,OPTIONS:1},...assessment};
  } finally {await response.body?.cancel();}
}

export async function main(argv=process.argv.slice(2)) {
  const options=parseArgs(argv);
  if (options.help) {console.log(USAGE);return;}
  const bytes=await readFile(options.intake);
  if (bytes.length>MAX_INPUT) throw new RangeError('Original SF70 report too large');
  const intake=JSON.parse(bytes.toString('utf8'));
  const report=await evaluate(intake,options);
  report.source.intakeSha256=createHash('sha256').update(bytes).digest('hex');
  const output=JSON.stringify(report,null,2)+'\n';
  if (options.out) await writeFile(options.out,output,{flag:'wx',mode:0o600});
  console.log(output);
  if (report.status==='INCONCLUSIVE') process.exitCode=3;
  else if (report.status==='PREFLIGHT_REMEDIATION') process.exitCode=2;
}

if (process.argv[1] && fileURLToPath(import.meta.url)===resolve(process.argv[1])) {
  main().catch(e=>{console.error('SF72: '+String(e.message));process.exitCode=1;});
}

// MIT. Accepted quotation scope applied atomically to the original merchant case.
import {parseWorkspace,serializeWorkspace,workspaceDraft} from './workspace-file.mjs';
