        dirty=generation!==stamp;
      }
      if(!dirty&&Object.hasOwn(result,'service')) {
        await applySavedService(result.service,{canReplace:()=>!destroyed&&identity===token&&generation===stamp});
        if(destroyed||identity!==token)return false;
