.cp-desk .cp-file-list p{margin:0}
.cp-desk progress{width:100%;max-width:40rem;height:.65rem;accent-color:#343b40}
.cp-desk .status.error{color:#202428;border-left:3px solid #24292d;padding-left:.8rem;font-weight:600}
.cp-desk :focus-visible{outline:2px solid #222d36;outline-offset:3px}
.cp-desk .cp-guide{max-width:90ch}
@media(max-width:600px){
 .cp-desk .section-heading{display:block}
 .cp-desk .section-heading>button{margin-top:.5rem}
 .cp-desk .cp-box{padding:.8rem}
 .cp-desk .cp-tabs{gap:.3rem}
